 s=qi[0];qr.append({"id":f"st3-l06-{qi}","lesson_id":L,"section_id":S[s],"fact_ids":[f"st3-l06-{fi}"],"question_en":en,"question_te":te,"options_en":oe,"options_te":ot,"correct_answer":k,"difficulty":d,"qtype":t,"explanation_en":F[[x[0] for x in F].index(fi)][2],"explanation_te":F[[x[0] for x in F].index(fi)][3],"review_status":"bilingual_approved"})
